1734 /// Try to simplify and/or of icmp with ctpop intrinsic.
1735 static Value *simplifyAndOrOfICmpsWithCtpop(ICmpInst *Cmp0, ICmpInst *Cmp1,
1736                                             bool IsAnd) {
1737   ICmpInst::Predicate Pred0, Pred1;
