1746   if (!IsAnd && Pred0 == ICmpInst::ICMP_EQ && Pred1 == ICmpInst::ICMP_NE)
1747     return Cmp1;
1748   // (ctpop(X) != C) && (X == 0) --> X == 0 where C > 0
1749   if (IsAnd && Pred0 == ICmpInst::ICMP_NE && Pred1 == ICmpInst::ICMP_EQ)
1750     return Cmp1;
1751 
1752   return nullptr;
1753 }
